package com.auth.multitenant

import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.nio.ByteBuffer

/**
 * Multi-tenant authentication library with iterative tenant resolution
 * and hierarchical permission checking.
 */

data class TenantConfig(
    val tenantId: String,
    val parentTenantId: String?,
    val maxDepth: Int = 64,
    val hmacSecret: ByteArray,
    val isolationLevel: IsolationLevel = IsolationLevel.STRICT
)

enum class IsolationLevel { STRICT, PERMISSIVE, INHERITED }

data class AuthToken(
    val subject: String,
    val tenantId: String,
    val claims: Map<String, String>,
    val signature: ByteArray
)

class TenantRegistry {
    private val tenants = ConcurrentHashMap<String, TenantConfig>()

    fun register(config: TenantConfig) {
        tenants[config.tenantId] = config
    }

    fun resolve(tenantId: String): TenantConfig? = tenants[tenantId]
}

class AuthenticationService(private val registry: TenantRegistry) {

    companion object {
        private const val MAX_ABSOLUTE_DEPTH = 32
    }

    /**
     * Validates token by iteratively checking tenant hierarchy.
     * Uses bounded iteration to prevent stack exhaustion.
     */
    fun authenticate(token: AuthToken): AuthResult {
        val config = registry.resolve(token.tenantId)
            ?: return AuthResult.Failure("Unknown tenant: ${token.tenantId}")
        return validateTokenIterative(token, config)
    }

    /**
     * Iterative validation through tenant hierarchy.
     * Bounded by absolute maximum depth constant.
     */
    private fun validateTokenIterative(
        token: AuthToken,
        initialConfig: TenantConfig
    ): AuthResult {
        var currentConfig = initialConfig
        val visited = HashSet<String>()
        var depth = 0

        while (depth < MAX_ABSOLUTE_DEPTH) {
            // Cycle detection prevents infinite loops
            if (!visited.add(currentConfig.tenantId)) {
                return AuthResult.Failure("Cycle detected in tenant hierarchy")
            }

            // Verify HMAC signature at current level
            val expectedSig = computeHmac(token, currentConfig)
            if (constantTimeEquals(expectedSig, token.signature)) {
                // Signature valid - check isolation
                return checkIsolation(token, currentConfig)
            }

            // If signature fails at this level, try parent tenant
            val parentId = currentConfig.parentTenantId
                ?: return AuthResult.Failure("Invalid signature for tenant ${currentConfig.tenantId}")

            val parentConfig = registry.resolve(parentId)
                ?: return AuthResult.Failure("Invalid signature for tenant ${currentConfig.tenantId}")

            currentConfig = parentConfig
            depth++
        }

        return AuthResult.Failure("Max tenant hierarchy depth exceeded")
    }

    private fun checkIsolation(token: AuthToken, config: TenantConfig): AuthResult {
        return when (config.isolationLevel) {
            IsolationLevel.STRICT -> {
                if (token.tenantId == config.tenantId) AuthResult.Success(token.subject, config.tenantId)
                else AuthResult.Failure("Strict isolation violation")
            }
            IsolationLevel.PERMISSIVE -> AuthResult.Success(token.subject, config.tenantId)
            IsolationLevel.INHERITED -> {
                // For inherited, accept if we reached this point through valid chain
                AuthResult.Success(token.subject, config.tenantId)
            }
        }
    }

    private fun computeHmac(token: AuthToken, config: TenantConfig): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(config.hmacSecret, "HmacSHA256"))
        // Length-prefix every field to eliminate boundary-ambiguity (canonicalization) attacks.
        updateWithLength(mac, token.subject.toByteArray(Charsets.UTF_8))
        updateWithLength(mac, token.tenantId.toByteArray(Charsets.UTF_8))
        val sortedClaims = token.claims.entries.sortedBy { it.key }
        updateWithLength(mac, ByteBuffer.allocate(4).putInt(sortedClaims.size).array())
        sortedClaims.forEach { (k, v) ->
            updateWithLength(mac, k.toByteArray(Charsets.UTF_8))
            updateWithLength(mac, v.toByteArray(Charsets.UTF_8))
        }
        return mac.doFinal()
    }

    private fun updateWithLength(mac: Mac, data: ByteArray) {
        // Prefix with an unambiguous 4-byte big-endian length so that
        // concatenated fields cannot be reinterpreted across boundaries.
        mac.update(ByteBuffer.allocate(4).putInt(data.size).array())
        mac.update(data)
    }

    private fun constantTimeEquals(a: ByteArray, b: ByteArray): Boolean {
        if (a.size != b.size) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].toInt() xor b[i].toInt())
        }
        return result == 0
    }
}

sealed class AuthResult {
    data class Success(val subject: String, val resolvedTenant: String) : AuthResult()
    data class Failure(val reason: String) : AuthResult()
}

/**
 * Tenant hierarchy builder for organizational structures.
 * Capped at safe maximum depth.
 */
fun buildTenantChain(registry: TenantRegistry, chainLength: Int, secret: ByteArray) {
    val safeLength = chainLength.coerceAtMost(32)
    for (i in 0 until safeLength) {
        val parentId = if (i > 0) "tenant-${i - 1}" else null
        registry.register(
            TenantConfig(
                tenantId = "tenant-$i",
                parentTenantId = parentId,
                maxDepth = safeLength,
                hmacSecret = secret,
                isolationLevel = IsolationLevel.STRICT
            )
        )
    }
}
